/**
 * Configuration entry point.
 *
 * Do not edit this file for site customisation:
 * - `src/config.user.ts` — your site settings and overrides
 * - `src/config.default.ts` — theme defaults and the typed schema
 *
 * This module deep-merges the two and exposes one read-only `config` object to
 * every page, component and build tool.
 */
import defaultConfig from './config.default';
import type { DeepPartial, RedefineConfig } from './config.default';
import userConfig from './config.user';

export type {
  Audit,
  DeepPartial,
  FontOption,
  NavLink,
  RedefineConfig,
  SocialLink,
  SocialQr,
  ThemeMode,
} from './config.default';

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

function deepMerge<T>(base: T, patch: DeepPartial<T> | undefined): T {
  if (patch === undefined) return base;

  // Arrays are intentional replacements: a user-supplied navigation or social
  // link list should not be concatenated with the defaults.
  if (Array.isArray(base) || Array.isArray(patch)) {
    return patch as T;
  }

  if (isPlainObject(base) && isPlainObject(patch)) {
    const result: Record<string, unknown> = { ...base };
    for (const key of Object.keys(patch)) {
      result[key] = deepMerge(
        (base as Record<string, unknown>)[key],
        (patch as Record<string, unknown>)[key] as never,
      );
    }
    return result as T;
  }

  return patch as T;
}

const config: RedefineConfig = deepMerge(defaultConfig, userConfig);

export default config;

/** Options exposed to the browser. Keep this JSON-serialisable. */
export function getClientConfig() {
  return {
    site: {
      title: config.site.title,
      subtitle: config.site.subtitle,
      language: config.site.language,
      base: config.site.base,
      url: config.site.url,
      dateFormat: config.site.dateFormat,
    },
    colors: config.colors,
    homeBanner: {
      enable: config.homeBanner.enable,
      style: config.homeBanner.style,
      subtitle: config.homeBanner.subtitle,
      socialLinks: config.homeBanner.socialLinks,
    },
    navbar: config.navbar,
    home: config.home,
    articles: {
      wordCount: config.articles.wordCount,
      codeBlock: config.articles.codeBlock,
      toc: config.articles.toc,
      lazyload: config.articles.lazyload,
      pangu: config.articles.pangu,
    },
    comment: config.comment,
    footer: {
      runtime: config.footer.runtime,
      start: config.footer.start,
    },
    global: {
      singlePage: config.global.singlePage,
      scrollProgress: config.global.scrollProgress,
      websiteCounter: config.global.websiteCounter,
    },
    plugins: {
      mermaid: config.plugins.mermaid,
      aplayer: config.plugins.aplayer,
    },
    pageTemplates: config.pageTemplates,
  };
}

export type ClientConfig = ReturnType<typeof getClientConfig>;
